import * as ecs from "@8thwall/ecs";
import { gameData } from "../core/game-data";

// -----------------------------------------------------
// CYBERWRAP HUD
// PART 1
// -----------------------------------------------------

let hudRoot: HTMLDivElement;

let tapPanel: HTMLDivElement;

let dashboard: HTMLDivElement;

let timeValue: HTMLSpanElement;

let scoreValue: HTMLSpanElement;

let foodValue: HTMLSpanElement;

let rulesPanel: HTMLDivElement;

let rulesButton: HTMLButtonElement;

let cameraButton: HTMLButtonElement;

let styleLoaded = false;

function injectFont() {
  if (document.getElementById("cw-font"))
    return;

  const link = document.createElement("link");

  link.id = "cw-font";

  link.rel = "stylesheet";

  link.href =
    "https://fonts.googleapis.com/css2?family=Orbitron:wght@400;600;800&display=swap";

  document.head.appendChild(link);
}

function injectStyles() {
  if (styleLoaded)
    return;

  styleLoaded = true;

  const style = document.createElement("style");

  style.innerHTML = `

body{

overflow:hidden;

}

/* ----------------------------- */

#cw-root{

position:fixed;

left:0;

top:0;

width:100%;

height:100%;

pointer-events:none;

z-index:999999;

font-family:'Orbitron',sans-serif;

}

/* ----------------------------- */

#cw-dashboard{

position:absolute;

left:18px;

top:18px;

min-width:235px;

padding:14px 18px;

background:

rgba(5,18,28,.55);

backdrop-filter:

blur(8px);

border:

1px solid rgba(0,255,255,.45);

box-shadow:

0 0 25px rgba(0,255,255,.18);

border-radius:14px;

}

/* ----------------------------- */

.cw-title{

font-size:13px;

letter-spacing:4px;

color:#62f6ff;

margin-bottom:12px;

font-weight:800;

}

/* ----------------------------- */

.cw-row{

display:flex;

justify-content:space-between;

margin:10px 0;

font-size:15px;

letter-spacing:2px;

color:white;

}

.cw-value{

font-weight:800;

color:#74ffff;

}

/* ----------------------------- */

#tap-place{

position:absolute;

left:50%;

top:50%;

transform:translate(-50%,-50%);

padding:24px 42px;

border:

2px solid cyan;

border-radius:16px;

background:

rgba(0,20,35,.7);

font-size:24px;

font-weight:800;

letter-spacing:6px;

color:white;

text-align:center;

box-shadow:

0 0 25px cyan;

animation:

cwBlink 1s infinite;

}

/* ----------------------------- */

#tap-place:before{

content:"";

position:absolute;

left:-18px;

right:-18px;

top:-18px;

bottom:-18px;

border:

1px solid rgba(0,255,255,.25);

}

/* ----------------------------- */

#cw-buttons{

position:absolute;

top:18px;

right:18px;

display:flex;

gap:10px;

pointer-events:auto;

}

.cw-btn{

width:54px;

height:54px;

border-radius:50%;

border:

1px solid rgba(0,255,255,.45);

background:

rgba(0,20,35,.6);

color:white;

font-size:22px;

cursor:pointer;

transition:.2s;

}

.cw-btn:hover{

transform:scale(1.08);

background:

rgba(0,255,255,.2);

}

/* ----------------------------- */

#cw-rules{

position:absolute;

right:18px;

top:88px;

width:260px;

padding:16px;

display:none;

background:

rgba(0,15,25,.82);

border:

1px solid cyan;

border-radius:14px;

pointer-events:auto;

color:white;

font-size:13px;

line-height:1.6;

}

#cw-rules h3{

margin:0 0 12px;

color:#74ffff;

letter-spacing:2px;

}

.lowTime{

color:#ff5555 !important;

animation:

cwPulse .8s infinite;

}

.scoreFlash{

animation:

cwScore .35s;

}

@keyframes cwBlink{

0%{opacity:1;}

50%{opacity:.35;}

100%{opacity:1;}

}

@keyframes cwPulse{

0%{transform:scale(1);}

50%{transform:scale(1.1);}

100%{transform:scale(1);}

}

@keyframes cwScore{

0%{transform:scale(1);}

50%{transform:scale(1.25);}

100%{transform:scale(1);}

}

`;

  document.head.appendChild(style);
}

function createHUD() {

  injectFont();

  injectStyles();

  hudRoot = document.createElement("div");

  hudRoot.id = "cw-root";

  dashboard = document.createElement("div");

  dashboard.id = "cw-dashboard";

  dashboard.innerHTML = `

<div class="cw-title">

CYBERWRAP OS

</div>

<div class="cw-row">

<span>TIME</span>

<span id="cw-time" class="cw-value">60</span>

</div>

<div class="cw-row">

<span>SCORE</span>

<span id="cw-score" class="cw-value">0</span>

</div>

<div class="cw-row">

<span>FOOD</span>

<span id="cw-food" class="cw-value">0 / 0</span>

</div>

`;

  hudRoot.appendChild(dashboard);

  tapPanel = document.createElement("div");

  tapPanel.id = "tap-place";

  tapPanel.innerHTML = `
TAP TO PLACE
`;

  hudRoot.appendChild(tapPanel);

  const buttons = document.createElement("div");

  buttons.id = "cw-buttons";

  rulesButton = document.createElement("button");

  rulesButton.className = "cw-btn";

  rulesButton.innerHTML = "📖";

  cameraButton = document.createElement("button");

  cameraButton.className = "cw-btn";

  cameraButton.innerHTML = "📹";

  buttons.appendChild(rulesButton);

  buttons.appendChild(cameraButton);

  hudRoot.appendChild(buttons);

  rulesPanel = document.createElement("div");

  rulesPanel.id = "cw-rules";

  rulesPanel.innerHTML = `

<h3>MISSION</h3>

Deliver the freshest wrap before time runs out.

<br><br>

🥙 Burrito = +20

🥩 Steak = +15

🍟 Fries = +10

🌶 Chili = +5

<br><br>

Collect as many ingredients as possible before the timer expires.

`;

  hudRoot.appendChild(rulesPanel);

  document.body.appendChild(hudRoot);

  timeValue = document.getElementById("cw-time") as HTMLSpanElement;

  scoreValue = document.getElementById("cw-score") as HTMLSpanElement;

  foodValue = document.getElementById("cw-food") as HTMLSpanElement;
}
// -----------------------------------------------------
// HUD Update Loop
// -----------------------------------------------------

let previousScore = 0;

function updateHUD() {
  if (!timeValue) return;

  // ------------------------------------
  // Hide TAP TO PLACE after placement
  // ------------------------------------

  if (gameData.driveZonePlaced) {
    tapPanel.style.display = "none";
  } else {
    tapPanel.style.display = "block";
  }

  // ------------------------------------
  // TIME
  // ------------------------------------

  const seconds = Math.max(0, Math.ceil(gameData.timeLeft));

  timeValue.textContent = seconds.toString();

  if (seconds <= 10) {
    timeValue.classList.add("lowTime");
  } else {
    timeValue.classList.remove("lowTime");
  }

  // ------------------------------------
  // SCORE
  // ------------------------------------

  if (gameData.score !== previousScore) {
    scoreValue.classList.remove("scoreFlash");

    void scoreValue.offsetWidth;

    scoreValue.classList.add("scoreFlash");

    previousScore = gameData.score;
  }

  scoreValue.textContent = gameData.score.toString();

  // ------------------------------------
  // FOOD
  // ------------------------------------

  foodValue.textContent =
    `${gameData.collectedCount} / ${gameData.totalSpawned}`;

  requestAnimationFrame(updateHUD);
}

// -----------------------------------------------------
// Rules Toggle
// -----------------------------------------------------

function setupButtons() {

  rulesButton.onclick = () => {

    if (
      rulesPanel.style.display === "block"
    ) {

      rulesPanel.style.display = "none";

    } else {

      rulesPanel.style.display = "block";

    }

  };

  // ------------------------------------
  // Recorder Button
  // ------------------------------------
  //
  // If you already created
  // record-button.ts,
  // simply dispatch an event.
  //
  // Otherwise you can replace
  // this later with your recorder.
  //
  // ------------------------------------

  cameraButton.onclick = () => {

    window.dispatchEvent(
      new CustomEvent("cyberwrap-record")
    );

  };

}

// -----------------------------------------------------
// Cleanup
// -----------------------------------------------------

function destroyHUD() {

  if (hudRoot) {

    hudRoot.remove();

  }

}

// -----------------------------------------------------
// ECS Component
// -----------------------------------------------------

ecs.registerComponent({

  name: "hud",

  stateMachine: ({ defineState }) => {

    defineState("ready")

      .initial()

      .onEnter(() => {

        console.log("[HUD] Initializing");

        createHUD();

        setupButtons();

        updateHUD();

        console.log("[HUD] Ready");

      });

  },

});

// -----------------------------------------------------
// Optional Hot Reload Cleanup
// -----------------------------------------------------

window.addEventListener("beforeunload", () => {

  destroyHUD();

});
